  @ApiProperty({ example: 'Ahmet Yılmaz', description: 'Koşumu yapan kişi', required: false })
  @IsString()
  @IsOptional()
  executedBy?: string = 'QA Tester';

  @ApiProperty({ example: 'ahmet.yilmaz@sirket.com', description: 'Tester e-posta', required: false })
