export class TestCasesController {
  constructor(private readonly testCasesService: TestCasesService) {}

  @Post()
  @ApiOperation({ summary: 'Yeni Test Case ve adımlarını oluştur (Kod otomatik uretilir: PRJ-TC-1 vb.)' })
  @ApiResponse({ status: 201, description: 'Test Case başarıyla oluşturuldu' })
  create(@Body() createTestCaseDto: CreateTestCaseDto) {
    return this.testCasesService.create(createTestCaseDto);
  }


  @Get()
  @ApiOperation({ summary: 'Bir Suite içindeki tüm Test Case\'leri listele' })
  @ApiQuery({ name: 'suiteId', required: true, description: 'Suite UUID' })
  findAllBySuite(@Query('suiteId') suiteId: string) {
    return this.testCasesService.findAllBySuite(suiteId);
  }

  @Get(':id')
  @ApiOperation({ summary: 'ID ile Test Case detaylarını adımlarıyla getir' })
  @ApiParam({ name: 'id', description: 'TestCase UUID' })
  findOne(@Param('id') id: string) {
    return this.testCasesService.findOne(id);
  }

  @Get('code/:code')
  @ApiOperation({ summary: 'Kod ile Test Case detaylarını getir (Örn: PRJ-TC-1)' })
  @ApiParam({ name: 'code', description: 'Test Case Kodu (PRJ-TC-1)' })
  findByCode(@Param('code') code: string) {
    return this.testCasesService.findByCode(code);
  }

  @Patch(':id/jira-link')
  @ApiOperation({ summary: 'Test Case ile Jira Story ID eşleştir (Jira Link API)' })
  @ApiParam({ name: 'id', description: 'TestCase UUID' })
  linkJiraStory(@Param('id') id: string, @Body() body: { jiraStoryKey?: string; jiraIssueUrl?: string }) {
    return this.testCasesService.linkJiraStory(id, body.jiraStoryKey, body.jiraIssueUrl);
  }

  @Patch(':id')
  @ApiOperation({ summary: 'Test Case ve adımlarını güncelle' })
  @ApiParam({ name: 'id', description: 'TestCase UUID' })
  update(@Param('id') id: string, @Body() updateTestCaseDto: UpdateTestCaseDto) {
    return this.testCasesService.update(id, updateTestCaseDto);
  }

  @Delete(':id')
  @ApiOperation({ summary: 'Test Case\'i sil' })
  @ApiParam({ name: 'id', description: 'TestCase UUID' })
  remove(@Param('id') id: string) {
    return this.testCasesService.remove(id);
  }
}

export class TestCasesService {
  constructor(private readonly prisma: PrismaService) {}

  async create(createTestCaseDto: CreateTestCaseDto) {
    const suite = await this.prisma.suite.findUnique({
      where: { id: createTestCaseDto.suiteId },
      include: { project: true },
    });

    if (!suite) {
      throw new NotFoundException(`Suite with ID ${createTestCaseDto.suiteId} not found`);
    }

    const projectKey = suite.project.key;

    // Count existing test cases for project to generate incrementing code e.g. PRJ-TC-1
    const totalCasesInProject = await this.prisma.testCase.count({
      where: {
        suite: {
          projectId: suite.projectId,
        },
      },
    });

    const nextNumber = totalCasesInProject + 1;
    const code = `${projectKey}-TC-${nextNumber}`;

    const { steps, ...caseData } = createTestCaseDto;

    return this.prisma.testCase.create({
      data: {
        ...caseData,
        code,
        steps: steps && steps.length > 0 ? {
          create: steps.map((step, idx) => ({
            stepNumber: step.stepNumber || idx + 1,
            action: step.action,
            expectedResult: step.expectedResult || '',
          })),
        } : undefined,
      },
      include: {
        steps: {
          orderBy: { stepNumber: 'asc' },
        },
      },
    });
  }

  async findAllBySuite(suiteId: string) {
    return this.prisma.testCase.findMany({
      where: { suiteId },
      include: {
        steps: {
          orderBy: { stepNumber: 'asc' },
        },
        results: {
          orderBy: { executedAt: 'desc' },
          take: 1,
        },
      },
      orderBy: { createdAt: 'asc' },
    });
  }

  async findOne(id: string) {
    const testCase = await this.prisma.testCase.findUnique({
      where: { id },
      include: {
        suite: {
          include: {
            project: true,
          },
        },
        steps: {
          orderBy: { stepNumber: 'asc' },
        },
        results: {
          orderBy: { executedAt: 'desc' },
          take: 1,
        },
      },
    });

    if (!testCase) {
      throw new NotFoundException(`TestCase with ID ${id} not found`);
    }

    return testCase;
  }

  async findByCode(code: string) {
    const testCase = await this.prisma.testCase.findUnique({
      where: { code },
      include: {
        steps: {
          orderBy: { stepNumber: 'asc' },
        },
        results: {
          orderBy: { executedAt: 'desc' },
          take: 1,
        },
      },
    });

    if (!testCase) {
      throw new NotFoundException(`TestCase with code ${code} not found`);
    }

    return testCase;
  }

  async update(id: string, updateTestCaseDto: UpdateTestCaseDto) {
    await this.findOne(id);

    const { steps, ...caseData } = updateTestCaseDto;

    // If steps are provided, replace existing steps
    if (steps) {
      await this.prisma.testStep.deleteMany({
        where: { testCaseId: id },
      });
    }

    return this.prisma.testCase.update({
      where: { id },
      data: {
        ...caseData,
        steps: steps ? {
          create: steps.map((step, idx) => ({
            stepNumber: step.stepNumber || idx + 1,
            action: step.action,
            expectedResult: step.expectedResult || '',
          })),
        } : undefined,
      },
      include: {
        steps: {
          orderBy: { stepNumber: 'asc' },
        },
      },
    });
  }


  async linkJiraStory(id: string, jiraStoryKey?: string, jiraIssueUrl?: string) {
    await this.findOne(id);
    const generatedUrl = jiraIssueUrl || (jiraStoryKey ? `https://company.atlassian.net/browse/${jiraStoryKey}` : null);

    return this.prisma.testCase.update({
      where: { id },
      data: {
        jiraStoryKey: jiraStoryKey || null,
        jiraIssueUrl: generatedUrl,
      },
    });
  }

  async remove(id: string) {
    await this.findOne(id);
    return this.prisma.testCase.delete({
      where: { id },
    });
  }
}

export class CreateTestCaseDto {
  @ApiProperty({ example: 'Geçerli kullanıcı adı ve şifre ile giriş yapma', description: 'Test Case başlığı' })
  @IsString()
  @IsNotEmpty()
  title: string;

  @ApiProperty({ example: 'Başarılı giriş senaryosu doğrulaması', description: 'Açıklama', required: false })
  @IsString()
  @IsOptional()
  description?: string;

  @ApiProperty({ example: 'MANUAL', description: 'Test yöntemi (MANUAL veya AUTOMATION)', required: false })
  @IsString()
  @IsOptional()
  executionType?: string = 'MANUAL';

  @ApiProperty({ enum: TestType, example: TestType.WEB, description: 'Test tipi' })
  @IsEnum(TestType)
  @IsOptional()
  type?: TestType = TestType.WEB;

  @ApiProperty({ enum: Priority, example: Priority.CRITICAL, description: 'Öncelik seviyesi' })
  @IsEnum(Priority)
  @IsOptional()
  priority?: Priority = Priority.NORMAL;

  @ApiProperty({ example: 'Sistemde kayıtlı kullanıcı olmalıdır', description: 'Ön koşul', required: false })
  @IsString()
