        {/* Status Filter Buttons */}
        <div className="flex items-center bg-slate-100 dark:bg-slate-800 p-1 rounded-xl space-x-1 text-xs overflow-x-auto no-scrollbar">
          <button
            onClick={() => setStatusFilter('ALL')}
