                      {run.status === 'IN_PROGRESS' && (
                        <span className="inline-flex items-center space-x-1.5 text-[10px] font-bold text-blue-600 dark:text-blue-400 bg-blue-500/10 px-2.5 py-0.5 rounded-full border border-blue-500/30">
