            <div className="max-w-5xl max-h-[85vh] p-2 overflow-auto">
              <img
                src={screenshotUrl}
                alt="Full Screenshot"
                className="max-w-full max-h-[80vh] object-contain rounded-xl border border-slate-800 shadow-2xl"
              />
            </div>
          </div>
        )}

        {/* Steps Table Section */}
