          <div className="flex items-center justify-between">
            <div className="flex items-center space-x-2">
              <ListOrdered className="w-4 h-4 text-blue-500" />
              <h3 className="text-xs font-bold uppercase tracking-wider text-slate-700 dark:text-slate-300">
                Test Adımları ({steps.length})
              </h3>
            </div>

            <button
              type="button"
              onClick={handleAddStep}
              className="flex items-center space-x-1.5 px-3 py-1.5 text-xs bg-white dark:bg-slate-800 hover:bg-slate-100 dark:hover:bg-slate-700 border border-slate-200 dark:border-slate-700 text-slate-700 dark:text-slate-200 rounded-lg transition-colors shadow-sm"
            >
              <Plus className="w-3.5 h-3.5 text-blue-500" />
              <span>Adım Ekle</span>
            </button>
          </div>

          {steps.length === 0 ? (
            <div className="p-8 border border-dashed border-slate-300 dark:border-slate-800 rounded-xl text-center text-slate-400 dark:text-slate-500 text-xs">
              <AlertCircle className="w-6 h-6 mx-auto mb-2 opacity-30 text-slate-400" />
              <p>Henüz tanımlanmış bir test adımı bulunmuyor.</p>
              <p className="text-[10px] mt-1 text-slate-500">
                "Adım Ekle" butonunu kullanarak test senaryosu adımlarını tanımlayabilirsiniz.
              </p>
            </div>
          ) : (
            <div className="border border-slate-200 dark:border-slate-800 rounded-xl overflow-hidden bg-white dark:bg-slate-900/40 shadow-sm">
              <div className="grid grid-cols-12 gap-2 bg-slate-100 dark:bg-slate-900/80 px-4 py-2 text-[11px] font-bold text-slate-600 dark:text-slate-400 uppercase tracking-wider border-b border-slate-200 dark:border-slate-800">
                <div className="col-span-1 text-center">#</div>
                <div className="col-span-6">Eylem (Action)</div>
                <div className="col-span-4">Beklenen Sonuç (Expected Result)</div>
                <div className="col-span-1 text-right">İşlem</div>
              </div>

              <div className="divide-y divide-slate-200 dark:divide-slate-800">
                {steps.map((step, idx) => (
                  <div key={idx} className="grid grid-cols-12 gap-2 p-3 items-start text-xs hover:bg-slate-50 dark:hover:bg-slate-800/30 transition-colors">
                    <div className="col-span-1 text-center pt-2 font-mono font-bold text-slate-400 dark:text-slate-500">
                      {step.stepNumber}
                    </div>

                    <div className="col-span-6">
                      <textarea
                        rows={2}
                        value={step.action}
                        onChange={(e) => handleStepChange(idx, 'action', e.target.value)}
                        placeholder="Örn: 'Giriş Yap' butonuna tıklanır..."
                        className="w-full bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-lg p-2 text-xs text-slate-800 dark:text-slate-200 placeholder-slate-400 dark:placeholder-slate-600 focus:outline-none focus:ring-1 focus:ring-blue-500 resize-none shadow-sm"
                      />
                    </div>

                    <div className="col-span-4">
                      <textarea
                        rows={2}
                        value={step.expectedResult || ''}
                        onChange={(e) => handleStepChange(idx, 'expectedResult', e.target.value)}
                        placeholder="Örn: Ana sayfaya yönlendirilir..."
                        className="w-full bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-lg p-2 text-xs text-slate-800 dark:text-slate-200 placeholder-slate-400 dark:placeholder-slate-600 focus:outline-none focus:ring-1 focus:ring-blue-500 resize-none shadow-sm"
                      />
                    </div>

                    <div className="col-span-1 text-right pt-2">
                      <button
                        type="button"
                        onClick={() => handleRemoveStep(idx)}
                        className="p-1 rounded hover:bg-red-500/10 text-slate-400 hover:text-red-500 transition-colors"
                        title="Adımı Sil"
                      >
                        <Trash2 className="w-3.5 h-3.5" />
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>

        {/* Execution History Section */}
        {testCase.results && testCase.results.length > 0 && (
          <div className="space-y-3 p-4 bg-white dark:bg-slate-900/60 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm">
            <div className="flex items-center justify-between">
              <div className="flex items-center space-x-2">
                <Clock className="w-4 h-4 text-indigo-500" />
                <h3 className="text-xs font-bold uppercase tracking-wider text-slate-700 dark:text-slate-300">
                  Koşum Geçmişi & Tüm Tekrar Koşuları ({testCase.results.length})
                </h3>
              </div>
              <span className="text-[10px] text-slate-400 font-mono">
                Son Koşu: {testCase.results[0].executedAt ? new Date(testCase.results[0].executedAt).toLocaleString('tr-TR') : '-'}
              </span>
            </div>

            <div className="space-y-2">
              {testCase.results.map((res, idx) => (
                <div
                  key={res.id || idx}
                  className="flex flex-col sm:flex-row sm:items-center justify-between p-3 rounded-lg bg-slate-50 dark:bg-slate-900/80 border border-slate-200 dark:border-slate-800 text-xs gap-2"
                >
                  <div className="flex items-center space-x-3 min-w-0">
                    {res.status === 'PASSED' && (
                      <span className="px-2 py-0.5 rounded bg-emerald-500/20 text-emerald-600 dark:text-emerald-400 font-mono font-bold text-[10px] shrink-0 border border-emerald-500/30">
                        PASSED
                      </span>
                    )}
                    {res.status === 'FAILED' && (
                      <span className="px-2 py-0.5 rounded bg-red-500/20 text-red-600 dark:text-red-400 font-mono font-bold text-[10px] shrink-0 border border-red-500/30">
                        FAILED
                      </span>
                    )}
                    {res.status === 'BLOCKED' && (
                      <span className="px-2 py-0.5 rounded bg-purple-500/20 text-purple-600 dark:text-purple-400 font-mono font-bold text-[10px] shrink-0 border border-purple-500/30">
                        BLOCKED
                      </span>
                    )}
                    {res.status === 'SKIPPED' && (
                      <span className="px-2 py-0.5 rounded bg-slate-500/20 text-slate-600 dark:text-slate-400 font-mono font-bold text-[10px] shrink-0 border border-slate-500/30">
                        SKIPPED
                      </span>
                    )}

                    <div className="space-y-0.5 min-w-0">
                      <div className="flex items-center space-x-2 text-[11px]">
                        <span className="font-mono text-slate-500 dark:text-slate-400 font-semibold">
                          {res.executedAt ? new Date(res.executedAt).toLocaleString('tr-TR') : ''}
                        </span>
                        {res.executedBy && (
                          <span className="text-slate-500 dark:text-slate-400">by {res.executedBy}</span>
                        )}
                        {res.executionMs && (
                          <span className="text-slate-400 font-mono text-[10px]">({res.executionMs} ms)</span>
                        )}
                      </div>
                      {res.errorMessage && (
                        <p className="text-red-500 dark:text-red-400 font-mono text-[11px] truncate">
                          Hata: {res.errorMessage}
                        </p>
                      )}
                    </div>
                  </div>

                  <div className="flex items-center space-x-2 shrink-0">
                    {res.jiraBugKey && (
                      <a
                        href={res.jiraBugUrl || `https://company.atlassian.net/browse/${res.jiraBugKey}`}
                        target="_blank"
                        rel="noreferrer"
                        className="text-[10px] font-mono text-red-500 hover:underline flex items-center space-x-1"
                      >
                        <span>Bug: {res.jiraBugKey}</span>
                      </a>
                    )}
                    {res.screenshotUrl && (
                      <button
                        type="button"
                        onClick={() => setScreenshotUrl(res.screenshotUrl || '')}
                        className="text-[10px] text-emerald-500 hover:underline flex items-center space-x-1"
                      >
                        <ImageIcon className="w-3 h-3" />
                        <span>Görsel</span>
                      </button>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </form>
    </main>
  );
};

export const EditSuiteModal: React.FC<EditSuiteModalProps> = ({
  isOpen,
  onClose,
  suite,
  suites,
  onUpdate,
  onDelete,
}) => {
  const [name, setName] = useState('');
  const [selectedParentId, setSelectedParentId] = useState<string>('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  useEffect(() => {
    if (suite) {
      setName(suite.name || '');
      setSelectedParentId(suite.parentId || '');
    }
  }, [suite, isOpen]);

  if (!isOpen || !suite) return null;

  const flattenSuites = (nodes: SuiteTreeNode[], depth = 0): Array<{ id: string; name: string; depth: number }> => {
    let result: Array<{ id: string; name: string; depth: number }> = [];
    nodes.forEach((node) => {
      if (node.id !== suite.id) {
        result.push({ id: node.id, name: node.name, depth });
        if (node.children && node.children.length > 0) {
          result = result.concat(flattenSuites(node.children, depth + 1));
        }
      }
    });
    return result;
  };

  const flatSuiteList = flattenSuites(suites);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!name.trim()) return;

    setIsSubmitting(true);
    try {
      await onUpdate(suite.id, {
        name: name.trim(),
        parentId: null,
      });
      onClose();
    } catch (err) {
      console.error('Error updating suite:', err);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleDelete = async () => {
    if (confirm(`"${suite.name}" isimli suite klasörünü ve içindekileri silmek istediğinizden emin misiniz?`)) {
      setIsDeleting(true);
      try {
        await onDelete(suite.id);
        onClose();
      } catch (err) {
        console.error('Error deleting suite:', err);
      } finally {
        setIsDeleting(false);
      }
    }
  };

  return (
    <div className="fixed inset-0 z-50 bg-black/60 backdrop-blur-sm flex items-center justify-center p-4">
      <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl w-full max-w-md shadow-2xl overflow-hidden animate-scaleUp text-slate-800 dark:text-slate-100">
        <div className="px-6 py-4 border-b border-slate-200 dark:border-slate-800 flex items-center justify-between bg-slate-50 dark:bg-slate-900/80">
          <div className="flex items-center space-x-2.5">
            <FolderEdit className="w-5 h-5 text-amber-500 dark:text-amber-400" />
            <h3 className="text-sm font-bold text-slate-800 dark:text-slate-100">Suite (Klasör) Düzenle</h3>
          </div>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-700 dark:hover:text-white p-1 rounded-lg">
            <X className="w-4 h-4" />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-6 space-y-4">
          <div className="space-y-1.5">
            <label className="text-xs font-semibold text-slate-700 dark:text-slate-300">Suite Adı</label>
            <input
              type="text"
              required
              placeholder="Suite adını girin..."
              value={name}
              onChange={(e) => setName(e.target.value)}
              className="w-full bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl px-3.5 py-2 text-xs text-slate-800 dark:text-slate-200 focus:outline-none focus:ring-1 focus:ring-amber-500 shadow-sm"
            />
          </div>

          <div className="flex items-center justify-between pt-4 border-t border-slate-200 dark:border-slate-800">
            <button
              type="button"
              onClick={handleDelete}
              disabled={isDeleting}
              className="flex items-center space-x-1.5 px-3 py-2 bg-red-500/10 hover:bg-red-500/20 text-red-600 dark:text-red-400 border border-red-500/20 text-xs font-semibold rounded-xl transition-colors disabled:opacity-50"
            >
              <Trash2 className="w-3.5 h-3.5" />
              <span>{isDeleting ? 'Siliniyor...' : 'Suite\'i Sil'}</span>
            </button>

            <div className="flex items-center space-x-2">
              <button
                type="button"
                onClick={onClose}
                className="px-4 py-2 bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 text-slate-700 dark:text-slate-300 text-xs font-semibold rounded-xl border border-slate-200 dark:border-slate-700"
              >
                İptal
              </button>

              <button
                type="submit"
                disabled={isSubmitting}
                className="flex items-center space-x-2 px-5 py-2 bg-amber-600 hover:bg-amber-500 text-white text-xs font-semibold rounded-xl shadow-lg shadow-amber-600/20 disabled:opacity-50"
              >
                <Save className="w-4 h-4" />
                <span>{isSubmitting ? 'Kaydediliyor...' : 'Kaydet'}</span>
              </button>
            </div>
          </div>
        </form>
      </div>
    </div>
  );
};

export const ThemeSelector: React.FC = () => {
  const { theme, setTheme, availableThemes } = useTheme();
  const [isOpen, setIsOpen] = useState(false);
  const menuRef = useRef<HTMLDivElement>(null);

  // Close menu when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const getThemeIcon = (id: ThemeId) => {
    switch (id) {
      case 'crimson-light':
        return (
          <div className="flex items-center space-x-0.5 text-rose-500">
            <Sun className="w-3.5 h-3.5" />
            <Sparkles className="w-3 h-3 text-rose-400" />
          </div>
        );
      case 'crimson-dark':
      default:
        return (
          <div className="flex items-center space-x-0.5 text-rose-400">
            <Moon className="w-3.5 h-3.5" />
            <Sparkles className="w-3 h-3 text-rose-400" />
          </div>
        );
    }
  };

  const activeThemeMeta = availableThemes.find((t) => t.id === theme) || availableThemes[0];

  return (
    <div className="relative inline-block text-left z-[100]" ref={menuRef}>
      {/* Theme Trigger Button */}
      <button
        type="button"
        onClick={() => setIsOpen((prev) => !prev)}
        className="flex items-center space-x-2 px-3 py-1.5 rounded-xl bg-slate-100 dark:bg-slate-800/90 hover:bg-slate-200 dark:hover:bg-slate-700/90 border border-slate-200 dark:border-slate-700/80 text-slate-700 dark:text-slate-200 transition-all shadow-sm focus:outline-none focus:ring-2 focus:ring-rose-500/50 cursor-pointer"
        title="Tema Seçici"
      >
        <div className="flex items-center space-x-1.5">
          {getThemeIcon(theme)}
          <span className="text-xs font-semibold">{activeThemeMeta.name}</span>
        </div>
        <div className="flex items-center space-x-0.5 ml-1">
          {activeThemeMeta.swatchColors.map((color, idx) => (
            <span
              key={idx}
              className="w-2.5 h-2.5 rounded-full border border-black/10 dark:border-white/10"
              style={{ backgroundColor: color }}
            />
          ))}
        </div>
      </button>

      {/* Dropdown Menu */}
      {isOpen && (
        <div className="absolute right-0 mt-2 w-80 rounded-2xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 shadow-2xl drop-shadow-2xl backdrop-blur-xl p-2 animate-in fade-in zoom-in-95 duration-150 z-[100]">
          <div className="px-3 py-2 border-b border-slate-100 dark:border-slate-800/80 flex items-center justify-between">
            <div className="flex items-center space-x-2">
              <Palette className="w-4 h-4 text-rose-500" />
              <span className="text-xs font-bold text-slate-800 dark:text-slate-200 uppercase tracking-wider">
                Crimson Coral Temaları
              </span>
            </div>
            <span className="text-[10px] text-rose-500 font-mono font-semibold">v2.0</span>
          </div>

          <div className="mt-1 space-y-1">
            {availableThemes.map((t) => {
              const isSelected = t.id === theme;
              return (
                <button
                  key={t.id}
                  onClick={() => {
                    setTheme(t.id);
                    setIsOpen(false);
                  }}
                  className={`w-full text-left px-3 py-2.5 rounded-xl flex items-center justify-between transition-all ${
                    isSelected
                      ? 'bg-rose-500/10 dark:bg-rose-500/15 border border-rose-500/30 text-slate-900 dark:text-white'
                      : 'hover:bg-slate-100 dark:hover:bg-slate-800/60 text-slate-600 dark:text-slate-300 border border-transparent'
                  }`}
                >
                  <div className="flex items-start space-x-3">
                    <div className="mt-0.5 p-1.5 rounded-lg bg-slate-100 dark:bg-slate-800">
                      {getThemeIcon(t.id)}
                    </div>
                    <div>
                      <div className="flex items-center space-x-2">
                        <span className="text-xs font-semibold">{t.name}</span>
                      </div>
                      <p className="text-[11px] text-slate-500 dark:text-slate-400 mt-0.5 line-clamp-1">
                        {t.description}
                      </p>
                    </div>
                  </div>

                  <div className="flex items-center space-x-2">
                    <div className="flex -space-x-1">
                      {t.swatchColors.map((color, idx) => (
                        <span
                          key={idx}
                          className="w-3.5 h-3.5 rounded-full border border-black/20 dark:border-white/20 shadow-sm"
                          style={{ backgroundColor: color }}
                        />
                      ))}
                    </div>
                    {isSelected && <Check className="w-4 h-4 text-rose-500 flex-shrink-0" />}
                  </div>
                </button>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
};

