              value={name}
              onChange={(e) => setName(e.target.value)}
              className="w-full bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl px-3.5 py-2 text-xs text-slate-800 dark:text-slate-200 focus:outline-none focus:ring-1 focus:ring-amber-500 shadow-sm"
            />
          </div>

          <div className="space-y-1.5">
            <label className="text-xs font-semibold text-slate-700 dark:text-slate-300">
              Bağlı Olduğu Test Planı
            </label>
            <div className="w-full bg-slate-100 dark:bg-slate-800/80 border border-slate-200 dark:border-slate-700 rounded-xl px-3.5 py-2 text-xs font-bold text-slate-800 dark:text-slate-200 flex items-center space-x-2">
              <span className="text-amber-500 font-mono">🚀</span>
              <span>{projectKey ? `[${projectKey}] ` : ''}{projectName || 'Aktif Test Planı'}</span>
            </div>
            <p className="text-[10px] text-slate-400">Suite'ler doğrudan Test Planı altında yer almaktadır.</p>
          </div>

          <div className="flex items-center justify-end space-x-3 pt-3">
            <button
              type="button"
              onClick={onClose}
              className="px-4 py-2 bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 text-slate-700 dark:text-slate-300 text-xs font-semibold rounded-xl border border-slate-200 dark:border-slate-700"
            >
              İptal
            </button>

            <button
              type="submit"
              disabled={isSubmitting}
              className="flex items-center space-x-2 px-5 py-2 bg-amber-600 hover:bg-amber-500 text-white text-xs font-semibold rounded-xl shadow-lg shadow-amber-600/20 disabled:opacity-50"
            >
              <FolderPlus className="w-4 h-4" />
              <span>{isSubmitting ? 'Oluşturuluyor...' : 'Suite Oluştur'}</span>
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export const DashboardView: React.FC<DashboardViewProps> = ({
  project,
  testCases,
  suites = [],
  onOpenManualRun,
  onOpenNewCase,
  onOpenNewSuite,
  onSelectCase,
}) => {
  const [dashboardTab, setDashboardTab] = useState<'SUITES' | 'METRICS'>('SUITES');
  const [suiteSearch, setSuiteSearch] = useState('');

  if (!project) {
    return (
      <div className="flex-1 flex flex-col items-center justify-center p-12 text-slate-400 dark:text-slate-500">
        <Layers className="w-16 h-16 mb-4 opacity-30 animate-pulse" />
        <p className="text-lg font-medium">Lütfen bir test planı seçin</p>
        <p className="text-sm text-slate-500 mt-1">Dashboard metriklerini ve Suite kartlarını görüntülemek için soldaki navigasyondan test planı seçebilirsiniz.</p>
      </div>
    );
  }

  // Flatten suites helper
  const flattenSuitesRecursive = (nodes: SuiteTreeNode[], parentPath: string = ''): FlattenedSuite[] => {
    let result: FlattenedSuite[] = [];
    nodes.forEach((node) => {
      const currentPath = parentPath ? `${parentPath} / ${node.name}` : node.name;

      // Get all child cases recursively
      const getChildCases = (n: SuiteTreeNode): TestCase[] => {
        let cases = n.testCases ? [...n.testCases] : [];
        if (n.children) {
          n.children.forEach((c) => {
            cases = cases.concat(getChildCases(c));
          });
        }
        return cases;
      };

      const allCasesInSuite = getChildCases(node);

      result.push({
        id: node.id,
        name: node.name,
        fullPath: currentPath,
        testCases: node.testCases || [],
        allCases: allCasesInSuite,
      });

      if (node.children && node.children.length > 0) {
        result = result.concat(flattenSuitesRecursive(node.children, currentPath));
      }
    });
    return result;
  };

  const flattenedSuites = flattenSuitesRecursive(suites);
  const filteredSuites = flattenedSuites.filter((s) =>
    s.fullPath.toLowerCase().includes(suiteSearch.toLowerCase())
  );

  // Calculate Metrics
  const totalCases = testCases.length;
  const automatedCases = testCases.filter((tc) => tc.type !== 'MANUAL').length;
  const automatedRatio = totalCases > 0 ? Math.round((automatedCases / totalCases) * 100) : 0;
  const jiraLinkedCases = testCases.filter((tc) => Boolean(tc.jiraStoryKey)).length;
  const traceabilityRatio = totalCases > 0 ? Math.round((jiraLinkedCases / totalCases) * 100) : 0;

  // Status metrics from latest result
  let passedCount = 0;
  let failedCount = 0;
  let blockedCount = 0;
  let skippedCount = 0;
  let untestedCount = 0;

  testCases.forEach((tc) => {
    const latest = tc.results && tc.results.length > 0 ? tc.results[0] : null;
    if (!latest) {
      untestedCount++;
    } else {
      switch (latest.status) {
        case 'PASSED':
          passedCount++;
          break;
        case 'FAILED':
          failedCount++;
          break;
        case 'BLOCKED':
          blockedCount++;
          break;
        case 'SKIPPED':
          skippedCount++;
          break;
        default:
          untestedCount++;
          break;
      }
    }
  });

  const executedCount = passedCount + failedCount + blockedCount + skippedCount;
  const passRate = executedCount > 0 ? Math.round((passedCount / executedCount) * 100) : 0;

  // Priority breakdown
  const blockerCount = testCases.filter((tc) => tc.priority === 'BLOCKER').length;
  const criticalCount = testCases.filter((tc) => tc.priority === 'CRITICAL').length;
  const normalCount = testCases.filter((tc) => tc.priority === 'NORMAL').length;
  const lowCount = testCases.filter((tc) => tc.priority === 'LOW').length;

  // Type breakdown
  const webCount = testCases.filter((tc) => tc.type === 'WEB').length;
  const mobileCount = testCases.filter((tc) => tc.type === 'MOBILE').length;
  const apiCount = testCases.filter((tc) => tc.type === 'API').length;

  // Recent executions list
  const recentExecutions: { testCase: TestCase; result: any }[] = [];
  testCases.forEach((tc) => {
    if (tc.results && tc.results.length > 0) {
      tc.results.forEach((res) => {
        recentExecutions.push({ testCase: tc, result: res });
      });
    }
  });
  recentExecutions.sort((a, b) => new Date(b.result.executedAt).getTime() - new Date(a.result.executedAt).getTime());
  const latestActivity = recentExecutions.slice(0, 7);

  return (
    <div className="flex-1 overflow-y-auto p-4 sm:p-6 space-y-6 bg-slate-50 dark:bg-[#090d16] text-slate-800 dark:text-slate-100 transition-colors duration-200">
      {/* Top Banner / Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 pb-4 border-b border-slate-200 dark:border-slate-800">
        <div className="flex items-center space-x-3">
          <div className="p-2.5 rounded-xl bg-rose-500/10 text-rose-600 dark:text-rose-400 border border-rose-500/20">
            <BarChart3 className="w-6 h-6" />
          </div>
          <div>
            <h1 className="text-xl font-bold tracking-tight">Top Dashboard (Yüksek Seviye Görünüm)</h1>
            <p className="text-xs text-slate-500 dark:text-slate-400 font-mono">
              [{project.key}] {project.name} &bull; {flattenedSuites.length} Test Suite &bull; {totalCases} Test Case
            </p>
          </div>
        </div>

        <div className="flex items-center space-x-3">
          {/* Sub Tab Switcher */}
          <div className="flex items-center bg-slate-200 dark:bg-slate-900 border border-slate-300 dark:border-slate-800 rounded-xl p-1 text-xs">
            <button
              onClick={() => setDashboardTab('SUITES')}
              className={`flex items-center space-x-1.5 px-3 py-1.5 rounded-lg font-semibold transition-all ${
                dashboardTab === 'SUITES'
                  ? 'bg-rose-600 text-white shadow-md shadow-rose-600/20'
                  : 'text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white'
              }`}
            >
              <FolderKanban className="w-3.5 h-3.5" />
              <span>Test Suites ({flattenedSuites.length})</span>
            </button>
            <button
              onClick={() => setDashboardTab('METRICS')}
              className={`flex items-center space-x-1.5 px-3 py-1.5 rounded-lg font-semibold transition-all ${
                dashboardTab === 'METRICS'
                  ? 'bg-rose-600 text-white shadow-md shadow-rose-600/20'
                  : 'text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white'
              }`}
            >
              <Activity className="w-3.5 h-3.5" />
              <span>Genel Analiz & Aktivite</span>
            </button>
          </div>

          {onOpenNewSuite && (
            <button
              onClick={onOpenNewSuite}
              className="hidden sm:inline-flex items-center space-x-1.5 px-3 py-1.5 text-xs font-semibold rounded-xl bg-amber-500/10 hover:bg-amber-500/20 text-amber-700 dark:text-amber-300 border border-amber-500/30 shadow-sm transition-all active:scale-95 cursor-pointer"
            >
              <FolderPlus className="w-3.5 h-3.5 text-amber-500" />
              <span>+ Yeni Suite Ekle</span>
            </button>
          )}
          <button
            onClick={onOpenNewCase}
            className="hidden sm:inline-flex items-center space-x-1.5 px-3 py-1.5 text-xs font-semibold rounded-xl bg-blue-500/10 hover:bg-blue-500/20 text-blue-700 dark:text-blue-300 border border-blue-500/30 shadow-sm transition-all active:scale-95 cursor-pointer"
          >
            <FilePlus className="w-3.5 h-3.5 text-blue-500" />
            <span>+ Yeni Case Ekle</span>
          </button>
          <button
            onClick={onOpenManualRun}
            className="flex items-center space-x-1.5 px-3.5 py-1.5 text-xs font-semibold rounded-xl bg-gradient-to-r from-emerald-600 to-teal-600 hover:from-emerald-500 hover:to-teal-500 text-white shadow-md shadow-emerald-600/20 transition-all active:scale-95 cursor-pointer"
          >
            <Play className="w-3.5 h-3.5 fill-current" />
            <span>Test Run</span>
          </button>
        </div>
      </div>

      {/* KPI Cards Summary Row */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        {/* Card 1: Total Cases */}
        <div className="p-4 rounded-2xl bg-white dark:bg-slate-900/80 border border-slate-200 dark:border-slate-800 shadow-sm space-y-3">
          <div className="flex items-center justify-between text-slate-500 dark:text-slate-400">
            <span className="text-xs font-medium uppercase tracking-wider">Toplam Test Case</span>
            <FileCheck className="w-4 h-4 text-blue-500" />
          </div>
          <div className="flex items-baseline justify-between">
            <span className="text-3xl font-extrabold font-mono tracking-tight">{totalCases}</span>
            <span className="text-xs px-2 py-0.5 rounded-full bg-blue-500/10 text-blue-600 dark:text-blue-400 border border-blue-500/20 font-medium">
              {automatedRatio}% Otomatik
            </span>
          </div>
          <div className="w-full bg-slate-100 dark:bg-slate-800 h-1.5 rounded-full overflow-hidden">
            <div className="bg-blue-500 h-full rounded-full" style={{ width: `${automatedRatio}%` }} />
          </div>
        </div>

        {/* Card 2: Pass Rate */}
        <div className="p-4 rounded-2xl bg-white dark:bg-slate-900/80 border border-slate-200 dark:border-slate-800 shadow-sm space-y-3">
          <div className="flex items-center justify-between text-slate-500 dark:text-slate-400">
            <span className="text-xs font-medium uppercase tracking-wider">Genel Başarı Oranı</span>
            <TrendingUp className="w-4 h-4 text-emerald-500" />
          </div>
          <div className="flex items-baseline justify-between">
            <span className="text-3xl font-extrabold font-mono text-emerald-600 dark:text-emerald-400 tracking-tight">
              {passRate}%
            </span>
            <span className="text-xs text-slate-500 dark:text-slate-400 font-mono">
              {passedCount}/{executedCount || 1} Koşuldu
            </span>
          </div>
          <div className="w-full bg-slate-100 dark:bg-slate-800 h-1.5 rounded-full overflow-hidden">
            <div className="bg-emerald-500 h-full rounded-full" style={{ width: `${passRate}%` }} />
          </div>
        </div>

        {/* Card 3: Failed & Blocked */}
        <div className="p-4 rounded-2xl bg-white dark:bg-slate-900/80 border border-slate-200 dark:border-slate-800 shadow-sm space-y-3">
          <div className="flex items-center justify-between text-slate-500 dark:text-slate-400">
            <span className="text-xs font-medium uppercase tracking-wider">Hata & Engel (Fail/Block)</span>
            <XCircle className="w-4 h-4 text-rose-500" />
          </div>
          <div className="flex items-baseline justify-between">
            <div className="flex items-center space-x-2">
              <span className="text-3xl font-extrabold font-mono text-rose-600 dark:text-rose-400 tracking-tight">
                {failedCount}
              </span>
              <span className="text-xs text-slate-400">Fail</span>
            </div>
            <span className="text-xs px-2 py-0.5 rounded-full bg-purple-500/10 text-purple-600 dark:text-purple-400 border border-purple-500/20 font-medium">
              {blockedCount} Blocked
            </span>
          </div>
          <div className="w-full bg-slate-100 dark:bg-slate-800 h-1.5 rounded-full overflow-hidden flex">
            <div className="bg-rose-500 h-full" style={{ width: `${executedCount ? (failedCount / executedCount) * 100 : 0}%` }} />
            <div className="bg-purple-500 h-full" style={{ width: `${executedCount ? (blockedCount / executedCount) * 100 : 0}%` }} />
          </div>
        </div>

        {/* Card 4: Total Suites */}
        <div className="p-4 rounded-2xl bg-white dark:bg-slate-900/80 border border-slate-200 dark:border-slate-800 shadow-sm space-y-3">
          <div className="flex items-center justify-between text-slate-500 dark:text-slate-400">
            <span className="text-xs font-medium uppercase tracking-wider">Test Suite Sayısı</span>
            <FolderKanban className="w-4 h-4 text-amber-500" />
          </div>
          <div className="flex items-baseline justify-between">
            <span className="text-3xl font-extrabold font-mono tracking-tight">{flattenedSuites.length}</span>
            <span className="text-xs text-slate-500 dark:text-slate-400 font-mono">
              {traceabilityRatio}% Jira Bağlı
            </span>
          </div>
          <div className="w-full bg-slate-100 dark:bg-slate-800 h-1.5 rounded-full overflow-hidden">
            <div className="bg-amber-500 h-full rounded-full" style={{ width: `${traceabilityRatio}%` }} />
          </div>
        </div>
      </div>

      {/* Main Content Tab 1: SUITE CARDS GRID VIEW */}
      {dashboardTab === 'SUITES' && (
        <div className="space-y-4">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
            <div>
              <h2 className="text-base font-bold text-slate-900 dark:text-slate-100 flex items-center space-x-2">
                <FolderKanban className="w-4 h-4 text-rose-500" />
                <span>Tüm Test Suite'leri (Kart Görünümü)</span>
              </h2>
              <p className="text-xs text-slate-500 dark:text-slate-400">
                Projede tanımlı tüm suite'lerin test sayıları, durumları ve hızlı aksiyonları.
              </p>
            </div>

            <input
              type="text"
              placeholder="Suite adı veya yolu ile filtrele..."
              value={suiteSearch}
              onChange={(e) => setSuiteSearch(e.target.value)}
              className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl px-3.5 py-1.5 text-xs text-slate-800 dark:text-slate-200 placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-rose-500 w-full sm:w-64"
            />
          </div>

          {filteredSuites.length === 0 ? (
            <div className="p-12 text-center border border-dashed border-slate-200 dark:border-slate-800 rounded-2xl bg-white dark:bg-slate-900/40 text-slate-400 text-xs">
              Kriterlere uygun test suite bulunamadı.
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5">
              {filteredSuites.map((s) => {
                // Calculate suite level stats
                let sPassed = 0;
                let sFailed = 0;
                let sBlocked = 0;
                let sSkipped = 0;
                let sUntested = 0;

                s.allCases.forEach((tc) => {
                  const lastRes = tc.results && tc.results.length > 0 ? tc.results[0] : null;
                  if (!lastRes) sUntested++;
                  else if (lastRes.status === 'PASSED') sPassed++;
                  else if (lastRes.status === 'FAILED') sFailed++;
                  else if (lastRes.status === 'BLOCKED') sBlocked++;
                  else if (lastRes.status === 'SKIPPED') sSkipped++;
                  else sUntested++;
                });

                const sTotal = s.allCases.length;
                const sExecuted = sPassed + sFailed + sBlocked + sSkipped;
                const sPassRate = sExecuted > 0 ? Math.round((sPassed / sExecuted) * 100) : 0;
                const sBlockerCritical = s.allCases.filter((tc) => tc.priority === 'BLOCKER' || tc.priority === 'CRITICAL').length;

                return (
                  <div
                    key={s.id}
                    className="group bg-white dark:bg-slate-900/90 border border-slate-200 dark:border-slate-800 hover:border-rose-500/50 dark:hover:border-rose-500/50 rounded-2xl p-5 shadow-sm hover:shadow-md transition-all duration-200 flex flex-col justify-between space-y-4"
                  >
                    {/* Suite Header */}
                    <div className="space-y-1.5">
                      <div className="flex items-center justify-between">
                        <span className="text-[10px] font-mono text-rose-500 dark:text-rose-400 font-semibold bg-rose-500/10 px-2 py-0.5 rounded border border-rose-500/20 truncate max-w-[200px]">
                          {s.fullPath}
                        </span>
                        <span className="text-[11px] font-mono font-bold bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 px-2 py-0.5 rounded-full shrink-0">
                          {sTotal} Case
                        </span>
                      </div>

                      <h3 className="text-base font-bold text-slate-900 dark:text-slate-100 group-hover:text-rose-500 transition-colors flex items-center justify-between">
                        <span>{s.name}</span>
                      </h3>
                    </div>

                    {/* Progress Bar & Status Badges */}
                    <div className="space-y-2">
                      <div className="flex items-center justify-between text-xs">
                        <span className="text-slate-500 dark:text-slate-400 font-medium">Koşu Başarı Oranı</span>
                        <span className="font-mono font-bold text-emerald-600 dark:text-emerald-400">%{sPassRate}</span>
                      </div>

                      <div className="w-full bg-slate-100 dark:bg-slate-800 h-2.5 rounded-full overflow-hidden flex shadow-inner">
                        <div className="bg-emerald-500 h-full" style={{ width: `${sTotal ? (sPassed / sTotal) * 100 : 0}%` }} title={`Passed: ${sPassed}`} />
                        <div className="bg-rose-500 h-full" style={{ width: `${sTotal ? (sFailed / sTotal) * 100 : 0}%` }} title={`Failed: ${sFailed}`} />
                        <div className="bg-purple-500 h-full" style={{ width: `${sTotal ? (sBlocked / sTotal) * 100 : 0}%` }} title={`Blocked: ${sBlocked}`} />
                        <div className="bg-slate-400 h-full" style={{ width: `${sTotal ? (sSkipped / sTotal) * 100 : 0}%` }} title={`Skipped: ${sSkipped}`} />
                      </div>

                      {/* Suite Mini Legend */}
                      <div className="grid grid-cols-4 gap-1.5 text-center text-[10px] font-mono pt-1">
                        <div className="bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 p-1 rounded border border-emerald-500/20">
                          <span className="font-bold">{sPassed}</span> Pass
                        </div>
                        <div className="bg-rose-500/10 text-rose-600 dark:text-rose-400 p-1 rounded border border-rose-500/20">
                          <span className="font-bold">{sFailed}</span> Fail
                        </div>
                        <div className="bg-purple-500/10 text-purple-600 dark:text-purple-400 p-1 rounded border border-purple-500/20">
                          <span className="font-bold">{sBlocked}</span> Block
                        </div>
                        <div className="bg-slate-500/10 text-slate-500 p-1 rounded border border-slate-500/20">
                          <span className="font-bold">{sUntested}</span> Untested
                        </div>
                      </div>
                    </div>

                    {/* Suite Footer & Action Buttons */}
                    <div className="pt-3 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-xs">
                      <span className="text-[11px] text-slate-400 font-mono">
                        {sBlockerCritical > 0 ? (
                          <span className="text-rose-500 font-semibold">{sBlockerCritical} Kritik Case</span>
                        ) : (
                          'Normal Öncelik'
                        )}
                      </span>

                      <div className="flex items-center space-x-2">
                        {s.allCases.length > 0 && onSelectCase && (
                          <button
                            onClick={() => onSelectCase(s.allCases[0])}
                            className="px-2.5 py-1 bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 text-slate-700 dark:text-slate-300 rounded-lg text-xs font-medium transition-colors flex items-center space-x-1"
                          >
                            <span>İncele</span>
                            <ChevronRight className="w-3 h-3" />
                          </button>
                        )}
                        <button
                          onClick={onOpenManualRun}
                          className="px-3 py-1 bg-emerald-600 hover:bg-emerald-500 text-white rounded-lg text-xs font-semibold shadow-sm transition-all flex items-center space-x-1"
                        >
                          <Play className="w-3 h-3 fill-current" />
                          <span>Koştur</span>
                        </button>
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      )}

      {/* Main Content Tab 2: METRICS & RECENT ACTIVITY */}
      {dashboardTab === 'METRICS' && (
        <div className="space-y-6">
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            {/* Status Distribution */}
            <div className="lg:col-span-2 p-5 rounded-2xl bg-white dark:bg-slate-900/80 border border-slate-200 dark:border-slate-800 shadow-sm space-y-4">
              <div className="flex items-center justify-between border-b border-slate-100 dark:border-slate-800 pb-3">
                <h3 className="text-sm font-bold text-slate-800 dark:text-slate-200 flex items-center space-x-2">
                  <Activity className="w-4 h-4 text-blue-500" />
                  <span>Test Durumu Genel Dağılımı</span>
                </h3>
                <span className="text-xs text-slate-500 dark:text-slate-400 font-mono">{totalCases} Test Senaryosu</span>
              </div>

              {/* Big Progress Bar */}
              <div className="space-y-2">
                <div className="w-full bg-slate-100 dark:bg-slate-800 h-4 rounded-xl overflow-hidden flex shadow-inner">
                  <div className="bg-emerald-500 h-full" style={{ width: `${totalCases ? (passedCount / totalCases) * 100 : 0}%` }} title={`Passed: ${passedCount}`} />
                  <div className="bg-rose-500 h-full" style={{ width: `${totalCases ? (failedCount / totalCases) * 100 : 0}%` }} title={`Failed: ${failedCount}`} />
                  <div className="bg-purple-500 h-full" style={{ width: `${totalCases ? (blockedCount / totalCases) * 100 : 0}%` }} title={`Blocked: ${blockedCount}`} />
                  <div className="bg-slate-400 h-full" style={{ width: `${totalCases ? (skippedCount / totalCases) * 100 : 0}%` }} title={`Skipped: ${skippedCount}`} />
                </div>

                {/* Badges Legend */}
                <div className="grid grid-cols-2 sm:grid-cols-5 gap-3 pt-2">
                  <div className="p-2.5 rounded-xl bg-emerald-500/10 border border-emerald-500/20 text-center">
                    <div className="flex items-center justify-center space-x-1 text-emerald-600 dark:text-emerald-400 font-bold text-xs">
                      <CheckCircle2 className="w-3.5 h-3.5" />
                      <span>PASSED</span>
                    </div>
                    <span className="text-lg font-mono font-extrabold text-emerald-700 dark:text-emerald-300">{passedCount}</span>
                  </div>

                  <div className="p-2.5 rounded-xl bg-rose-500/10 border border-rose-500/20 text-center">
                    <div className="flex items-center justify-center space-x-1 text-rose-600 dark:text-rose-400 font-bold text-xs">
                      <XCircle className="w-3.5 h-3.5" />
                      <span>FAILED</span>
                    </div>
                    <span className="text-lg font-mono font-extrabold text-rose-700 dark:text-rose-300">{failedCount}</span>
                  </div>

                  <div className="p-2.5 rounded-xl bg-purple-500/10 border border-purple-500/20 text-center">
                    <div className="flex items-center justify-center space-x-1 text-purple-600 dark:text-purple-400 font-bold text-xs">
                      <Slash className="w-3.5 h-3.5" />
                      <span>BLOCKED</span>
                    </div>
                    <span className="text-lg font-mono font-extrabold text-purple-700 dark:text-purple-300">{blockedCount}</span>
                  </div>

                  <div className="p-2.5 rounded-xl bg-slate-500/10 border border-slate-500/20 text-center">
                    <div className="flex items-center justify-center space-x-1 text-slate-600 dark:text-slate-400 font-bold text-xs">
                      <Clock className="w-3.5 h-3.5" />
                      <span>UNTESTED</span>
                    </div>
                    <span className="text-lg font-mono font-extrabold text-slate-700 dark:text-slate-300">{untestedCount}</span>
                  </div>

                  <div className="p-2.5 rounded-xl bg-blue-500/10 border border-blue-500/20 text-center">
                    <div className="flex items-center justify-center space-x-1 text-blue-600 dark:text-blue-400 font-bold text-xs">
                      <Zap className="w-3.5 h-3.5" />
                      <span>KOŞULDU</span>
                    </div>
                    <span className="text-lg font-mono font-extrabold text-blue-700 dark:text-blue-300">{executedCount}</span>
                  </div>
                </div>
              </div>
            </div>

            {/* Priority & Platform Type breakdown */}
            <div className="p-5 rounded-2xl bg-white dark:bg-slate-900/80 border border-slate-200 dark:border-slate-800 shadow-sm space-y-4">
              <h3 className="text-sm font-bold text-slate-800 dark:text-slate-200 border-b border-slate-100 dark:border-slate-800 pb-3">
                Öncelik & Platform Dağılımı
              </h3>

              <div className="space-y-3 text-xs">
                {/* Priority Bars */}
                <div>
                  <div className="flex justify-between text-slate-500 dark:text-slate-400 mb-1">
                    <span>Blocker & Critical</span>
                    <span className="font-mono font-bold text-rose-500">{blockerCount + criticalCount} case</span>
                  </div>
                  <div className="w-full bg-slate-100 dark:bg-slate-800 h-2 rounded-full overflow-hidden">
                    <div
                      className="bg-rose-500 h-full rounded-full"
                      style={{ width: `${totalCases ? ((blockerCount + criticalCount) / totalCases) * 100 : 0}%` }}
                    />
                  </div>
                </div>

                <div>
                  <div className="flex justify-between text-slate-500 dark:text-slate-400 mb-1">
                    <span>Normal & Low</span>
                    <span className="font-mono font-bold text-blue-500">{normalCount + lowCount} case</span>
                  </div>
                  <div className="w-full bg-slate-100 dark:bg-slate-800 h-2 rounded-full overflow-hidden">
                    <div
                      className="bg-blue-500 h-full rounded-full"
                      style={{ width: `${totalCases ? ((normalCount + lowCount) / totalCases) * 100 : 0}%` }}
                    />
                  </div>
                </div>

                {/* Platform types */}
                <div className="pt-3 border-t border-slate-100 dark:border-slate-800 grid grid-cols-3 gap-2 text-center">
                  <div className="p-2 rounded-xl bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700/50">
                    <Globe className="w-4 h-4 text-emerald-500 mx-auto mb-1" />
                    <span className="text-[10px] text-slate-400 uppercase font-semibold">Web</span>
                    <p className="font-mono font-bold">{webCount}</p>
                  </div>

                  <div className="p-2 rounded-xl bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700/50">
                    <Smartphone className="w-4 h-4 text-purple-500 mx-auto mb-1" />
                    <span className="text-[10px] text-slate-400 uppercase font-semibold">Mobile</span>
                    <p className="font-mono font-bold">{mobileCount}</p>
                  </div>

                  <div className="p-2 rounded-xl bg-slate-50 dark:bg-slate-800/50 border border-slate-200 dark:border-slate-700/50">
                    <Code className="w-4 h-4 text-cyan-500 mx-auto mb-1" />
                    <span className="text-[10px] text-slate-400 uppercase font-semibold">API</span>
                    <p className="font-mono font-bold">{apiCount}</p>
                  </div>
                </div>
              </div>
            </div>
          </div>

          {/* Bottom Section: Recent Execution Feed */}
          <div className="p-5 rounded-2xl bg-white dark:bg-slate-900/80 border border-slate-200 dark:border-slate-800 shadow-sm space-y-4">
            <div className="flex items-center justify-between border-b border-slate-100 dark:border-slate-800 pb-3">
              <h3 className="text-sm font-bold text-slate-800 dark:text-slate-200 flex items-center space-x-2">
                <Clock className="w-4 h-4 text-indigo-500" />
                <span>Son Test Koşuları Aktivitesi</span>
              </h3>
              <span className="text-xs text-slate-500 dark:text-slate-400">Son {latestActivity.length} aktivite</span>
            </div>

            {latestActivity.length === 0 ? (
              <div className="text-center py-8 text-slate-400 dark:text-slate-500 text-xs">
                Henüz test koşusu yapılmadı. "Test Run" butonu ile ilk test koşunuzu başlatabilirsiniz.
              </div>
            ) : (
              <div className="space-y-2">
                {latestActivity.map(({ testCase, result }, idx) => (
                  <div
                    key={idx}
                    onClick={() => onSelectCase && onSelectCase(testCase)}
                    className="flex items-center justify-between p-3 rounded-xl bg-slate-50 dark:bg-slate-800/40 hover:bg-slate-100 dark:hover:bg-slate-800 border border-slate-200/70 dark:border-slate-700/50 transition-colors cursor-pointer text-xs"
                  >
                    <div className="flex items-center space-x-3 min-w-0">
                      {result.status === 'PASSED' && (
                        <span className="px-2 py-0.5 rounded bg-emerald-500/20 text-emerald-600 dark:text-emerald-400 font-mono font-bold text-[10px] shrink-0">
                          PASS
                        </span>
                      )}
                      {result.status === 'FAILED' && (
                        <span className="px-2 py-0.5 rounded bg-rose-500/20 text-rose-600 dark:text-rose-400 font-mono font-bold text-[10px] shrink-0">
                          FAIL
                        </span>
                      )}
                      {result.status === 'BLOCKED' && (
                        <span className="px-2 py-0.5 rounded bg-purple-500/20 text-purple-600 dark:text-purple-400 font-mono font-bold text-[10px] shrink-0">
                          BLOCK
                        </span>
                      )}
                      {result.status === 'SKIPPED' && (
                        <span className="px-2 py-0.5 rounded bg-slate-500/20 text-slate-600 dark:text-slate-400 font-mono font-bold text-[10px] shrink-0">
                          SKIP
                        </span>
                      )}

                      <span className="font-mono text-[11px] font-bold text-slate-400 shrink-0">{testCase.code}</span>
                      <span className="font-medium truncate text-slate-700 dark:text-slate-200">{testCase.title}</span>
                    </div>

                    <div className="flex items-center space-x-3 shrink-0 text-[11px] text-slate-400 font-mono">
                      <span>{new Date(result.executedAt).toLocaleTimeString('tr-TR', { hour: '2-digit', minute: '2-digit' })}</span>
                      {result.executedBy && <span className="hidden sm:inline text-slate-500">by {result.executedBy}</span>}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export const SuiteCasesView: React.FC<SuiteCasesViewProps> = ({
  suite,
  onSelectCase,
  onAddCaseInSuite,
  onRunCase,
  onRunSuite,
  onClose,
}) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState<StatusFilter>('ALL');
  const [priorityFilter, setPriorityFilter] = useState<string>('ALL');
  const [typeFilter, setTypeFilter] = useState<string>('ALL');

  if (!suite) return null;

  const testCases = suite.testCases || [];

  // Calculate suite stats
  const stats = {
    total: testCases.length,
    passed: testCases.filter((c) => c.results && c.results.length > 0 && c.results[0].status === 'PASSED').length,
    failed: testCases.filter((c) => c.results && c.results.length > 0 && c.results[0].status === 'FAILED').length,
    blocked: testCases.filter((c) => c.results && c.results.length > 0 && c.results[0].status === 'BLOCKED').length,
    untested: testCases.filter((c) => !c.results || c.results.length === 0).length,
  };

  const passRate = stats.total > 0 ? Math.round((stats.passed / stats.total) * 100) : 0;

  // Filter test cases
  const filteredCases = testCases.filter((tc) => {
    const matchesSearch = searchQuery
      ? tc.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
        tc.code.toLowerCase().includes(searchQuery.toLowerCase()) ||
        (tc.description && tc.description.toLowerCase().includes(searchQuery.toLowerCase()))
      : true;

    const latestStatus = tc.results && tc.results.length > 0 ? tc.results[0].status : 'UNTESTED';
    const matchesStatus =
      statusFilter === 'ALL'
        ? true
        : statusFilter === 'UNTESTED'
        ? !tc.results || tc.results.length === 0
        : latestStatus === statusFilter;

    const matchesPriority = priorityFilter === 'ALL' ? true : tc.priority === priorityFilter;
    const matchesType = typeFilter === 'ALL' ? true : tc.type === typeFilter;

    return matchesSearch && matchesStatus && matchesPriority && matchesType;
  });

  const getPriorityBadge = (priority: Priority) => {
    switch (priority) {
      case 'BLOCKER':
        return 'bg-red-500/10 dark:bg-red-500/20 text-red-600 dark:text-red-400 border-red-500/30';
      case 'CRITICAL':
        return 'bg-amber-500/10 dark:bg-amber-500/20 text-amber-600 dark:text-amber-400 border-amber-500/30';
      case 'NORMAL':
        return 'bg-blue-500/10 dark:bg-blue-500/20 text-blue-600 dark:text-blue-400 border-blue-500/30';
      case 'LOW':
        return 'bg-slate-500/10 dark:bg-slate-500/20 text-slate-600 dark:text-slate-400 border-slate-500/30';
      default:
        return 'bg-slate-500/10 dark:bg-slate-500/20 text-slate-600 dark:text-slate-400 border-slate-500/30';
    }
  };

  const getTypeBadge = (type: TestType) => {
    switch (type) {
      case 'WEB':
        return 'bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border-emerald-500/30';
      case 'MOBILE':
        return 'bg-purple-500/10 text-purple-600 dark:text-purple-400 border-purple-500/30';
      case 'API':
        return 'bg-cyan-500/10 text-cyan-600 dark:text-cyan-400 border-cyan-500/30';
      default:
        return 'bg-slate-500/10 text-slate-600 dark:text-slate-400 border-slate-500/30';
    }
  };

  const renderStatusPill = (tc: TestCase) => {
    const latestResult = tc.results && tc.results.length > 0 ? tc.results[0] : null;
    if (!latestResult) {
      return (
        <span className="text-[10px] px-2 py-0.5 rounded bg-slate-200 dark:bg-slate-800 text-slate-500 dark:text-slate-400 border border-slate-300 dark:border-slate-700/50 font-mono font-medium">
          UNTESTED
        </span>
      );
    }

    switch (latestResult.status) {
      case 'PASSED':
        return (
          <span className="flex items-center space-x-1 text-[10px] px-2 py-0.5 rounded bg-emerald-500/10 dark:bg-emerald-500/20 text-emerald-600 dark:text-emerald-400 border border-emerald-500/30 font-mono font-bold">
            <CheckCircle2 className="w-3 h-3" />
            <span>PASSED</span>
          </span>
        );
      case 'FAILED':
        return (
          <span
            className="flex items-center space-x-1 text-[10px] px-2 py-0.5 rounded bg-red-500/10 dark:bg-red-500/20 text-red-600 dark:text-red-400 border border-red-500/30 font-mono font-bold"
            title={latestResult.errorMessage || 'Test Başarısız Oldu'}
          >
            <XCircle className="w-3 h-3" />
            <span>FAILED</span>
          </span>
        );
      case 'SKIPPED':
        return (
          <span className="flex items-center space-x-1 text-[10px] px-2 py-0.5 rounded bg-slate-500/10 dark:bg-slate-500/20 text-slate-600 dark:text-slate-400 border border-slate-500/30 font-mono font-bold">
            <SkipForward className="w-3 h-3" />
            <span>SKIPPED</span>
          </span>
        );
      case 'BLOCKED':
        return (
          <span className="flex items-center space-x-1 text-[10px] px-2 py-0.5 rounded bg-purple-500/10 dark:bg-purple-500/20 text-purple-600 dark:text-purple-400 border border-purple-500/30 font-mono font-bold">
            <Slash className="w-3 h-3" />
            <span>BLOCKED</span>
          </span>
        );
      default:
        return null;
    }
  };

  return (
    <main className="flex-1 overflow-y-auto bg-slate-50 dark:bg-[#090d16] text-slate-800 dark:text-slate-100 p-6 space-y-6 transition-colors duration-200">
      {/* Suite Header Section */}
      <div className="bg-white dark:bg-slate-900/80 border border-slate-200 dark:border-slate-800 rounded-2xl p-5 shadow-sm space-y-4">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div className="flex items-center space-x-3">
            <div className="w-11 h-11 rounded-xl bg-amber-500/10 text-amber-500 flex items-center justify-center border border-amber-500/20 shrink-0">
              <FolderOpen className="w-6 h-6" />
            </div>
            <div>
              <div className="flex items-center space-x-2">
                <h2 className="text-xl font-bold text-slate-900 dark:text-slate-100">{suite.name}</h2>
                <span className="text-xs px-2.5 py-0.5 rounded-full bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400 border border-slate-200 dark:border-slate-700 font-mono font-bold">
                  {stats.total} Senaryo
                </span>
              </div>
              <p className="text-xs text-slate-500 dark:text-slate-400 mt-0.5">
                Bu klasördeki (Suite) tüm test senaryolarının kart görünümü
              </p>
            </div>
          </div>

          <div className="flex items-center space-x-2">
            {onRunSuite && testCases.length > 0 && (
              <button
                type="button"
                onClick={() => onRunSuite(suite)}
                className="flex items-center space-x-1.5 px-3.5 py-2 bg-gradient-to-r from-emerald-600 to-teal-600 hover:from-emerald-500 hover:to-teal-500 text-white text-xs font-semibold rounded-xl shadow-md shadow-emerald-600/20 transition-all active:scale-95 cursor-pointer"
              >
                <Play className="w-4 h-4 fill-current" />
                <span>Suite'i Koştur ({testCases.length})</span>
              </button>
            )}

            <button
              type="button"
              onClick={() => onAddCaseInSuite(suite.id)}
              className="flex items-center space-x-1.5 px-3.5 py-2 bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-500 hover:to-indigo-500 text-white text-xs font-semibold rounded-xl shadow-md shadow-blue-500/20 transition-all active:scale-95 cursor-pointer"
            >
              <Plus className="w-4 h-4" />
              <span>Yeni Case Ekle</span>
            </button>

            {onClose && (
              <button
                type="button"
                onClick={onClose}
                className="p-2 rounded-xl bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 text-slate-500 dark:text-slate-400 hover:text-slate-800 dark:hover:text-white border border-slate-200 dark:border-slate-700 transition-colors"
                title="Görünümü Kapat"
              >
                <X className="w-4 h-4" />
              </button>
            )}
          </div>
        </div>

        {/* Stats Summary Bar */}
        <div className="grid grid-cols-2 sm:grid-cols-5 gap-3 pt-3 border-t border-slate-100 dark:border-slate-800/80">
          <div className="bg-slate-50 dark:bg-slate-950/50 p-2.5 rounded-xl border border-slate-200/60 dark:border-slate-800/60">
            <span className="text-[10px] font-semibold text-slate-400 uppercase">Başarı Oranı</span>
            <div className="text-base font-bold text-emerald-500">{passRate}%</div>
          </div>
          <div className="bg-slate-50 dark:bg-slate-950/50 p-2.5 rounded-xl border border-slate-200/60 dark:border-slate-800/60">
            <span className="text-[10px] font-semibold text-slate-400 uppercase">Passed</span>
            <div className="text-base font-bold text-emerald-600 dark:text-emerald-400">{stats.passed}</div>
          </div>
          <div className="bg-slate-50 dark:bg-slate-950/50 p-2.5 rounded-xl border border-slate-200/60 dark:border-slate-800/60">
            <span className="text-[10px] font-semibold text-slate-400 uppercase">Failed</span>
            <div className="text-base font-bold text-red-600 dark:text-red-400">{stats.failed}</div>
          </div>
          <div className="bg-slate-50 dark:bg-slate-950/50 p-2.5 rounded-xl border border-slate-200/60 dark:border-slate-800/60">
            <span className="text-[10px] font-semibold text-slate-400 uppercase">Blocked</span>
            <div className="text-base font-bold text-purple-600 dark:text-purple-400">{stats.blocked}</div>
          </div>
          <div className="bg-slate-50 dark:bg-slate-950/50 p-2.5 rounded-xl border border-slate-200/60 dark:border-slate-800/60">
            <span className="text-[10px] font-semibold text-slate-400 uppercase">Koşulmadı</span>
            <div className="text-base font-bold text-slate-500">{stats.untested}</div>
          </div>
        </div>
      </div>

      {/* Toolbar & Filter Bar */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 bg-white dark:bg-slate-900/60 p-3 rounded-xl border border-slate-200 dark:border-slate-800 shadow-sm">
        {/* Search Input */}
        <div className="relative flex-1 max-w-md">
          <Search className="w-3.5 h-3.5 text-slate-400 absolute left-3 top-1/2 -translate-y-1/2" />
          <input
            type="text"
            placeholder="Senaryo başlığı, kod veya açıklama ara..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-lg text-xs text-slate-800 dark:text-slate-200 placeholder-slate-400 dark:placeholder-slate-500 pl-9 pr-3 py-1.5 focus:outline-none focus:ring-1 focus:ring-blue-500 transition-colors"
          />
        </div>

        {/* Filter Dropdowns */}
        <div className="flex items-center space-x-2 overflow-x-auto text-xs">
          {/* Status Filter */}
          <select
            value={statusFilter}
            onChange={(e) => setStatusFilter(e.target.value as StatusFilter)}
            className="bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 text-slate-700 dark:text-slate-300 rounded-lg px-2.5 py-1.5 text-xs font-medium focus:outline-none focus:ring-1 focus:ring-blue-500 cursor-pointer"
          >
            <option value="ALL">Tüm Durumlar</option>
            <option value="PASSED">Passed</option>
            <option value="FAILED">Failed</option>
            <option value="BLOCKED">Blocked</option>
            <option value="UNTESTED">Untested</option>
          </select>

          {/* Priority Filter */}
          <select
            value={priorityFilter}
            onChange={(e) => setPriorityFilter(e.target.value)}
            className="bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 text-slate-700 dark:text-slate-300 rounded-lg px-2.5 py-1.5 text-xs font-medium focus:outline-none focus:ring-1 focus:ring-blue-500 cursor-pointer"
          >
            <option value="ALL">Tüm Öncelikler</option>
            <option value="BLOCKER">🔴 BLOCKER</option>
            <option value="CRITICAL">🟠 CRITICAL</option>
            <option value="NORMAL">🔵 NORMAL</option>
            <option value="LOW">⚪ LOW</option>
          </select>

          {/* Type Filter */}
          <select
            value={typeFilter}
            onChange={(e) => setTypeFilter(e.target.value)}
            className="bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 text-slate-700 dark:text-slate-300 rounded-lg px-2.5 py-1.5 text-xs font-medium focus:outline-none focus:ring-1 focus:ring-blue-500 cursor-pointer"
          >
            <option value="ALL">Tüm Tipler</option>
            <option value="WEB">🌐 WEB</option>
            <option value="MOBILE">📱 MOBILE</option>
            <option value="API">⚡ API</option>
            <option value="MANUAL">📋 MANUAL</option>
          </select>
        </div>
      </div>

      {/* Cards Grid */}
      {filteredCases.length === 0 ? (
        <div className="flex flex-col items-center justify-center p-12 text-center border-2 border-dashed border-slate-200 dark:border-slate-800 rounded-2xl bg-white dark:bg-slate-900/40 text-slate-400 dark:text-slate-500">
          <Layers className="w-10 h-10 mb-3 opacity-30 text-slate-400" />
          <h4 className="text-sm font-semibold text-slate-700 dark:text-slate-300">Test Senaryosu Bulunamadı</h4>
          <p className="text-xs text-slate-500 mt-1 max-w-sm">
            Bu suite içerisinde arama kriterlerinize uygun test senaryosu bulunmuyor veya henüz test senaryosu eklenmemiş.
          </p>
          <button
            type="button"
            onClick={() => onAddCaseInSuite(suite.id)}
            className="mt-4 px-3.5 py-1.5 bg-blue-600 hover:bg-blue-500 text-white text-xs font-semibold rounded-lg shadow-sm transition-all"
          >
            + Yeni Senaryo Oluştur
          </button>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {filteredCases.map((tc) => (
            <div
              key={tc.id}
              onClick={() => onSelectCase(tc)}
              className="group bg-white dark:bg-slate-900/80 hover:bg-slate-50/90 dark:hover:bg-slate-800/80 border border-slate-200 dark:border-slate-800 hover:border-blue-500/50 dark:hover:border-blue-500/50 rounded-2xl p-4 shadow-sm hover:shadow-md transition-all duration-200 cursor-pointer flex flex-col justify-between space-y-3 relative overflow-hidden"
            >
              {/* Card Header: Code & Badges */}
              <div className="space-y-2">
                <div className="flex items-center justify-between gap-2">
                  <span className="font-mono text-[11px] font-bold px-2 py-0.5 rounded-md bg-blue-500/10 text-blue-600 dark:text-blue-400 border border-blue-500/20 flex items-center space-x-1 shrink-0">
                    <FileCode2 className="w-3 h-3" />
                    <span>{tc.code}</span>
                  </span>

                  <div className="flex items-center space-x-1.5">
                    {/* Status Pill */}
                    {renderStatusPill(tc)}

                    {/* Priority Badge */}
                    <span
                      className={`text-[9px] px-1.5 py-0.5 rounded border font-mono font-bold ${getPriorityBadge(
                        tc.priority
                      )}`}
                    >
                      {tc.priority}
                    </span>
                  </div>
                </div>

                {/* Title */}
                <h3 className="text-sm font-bold text-slate-900 dark:text-slate-100 group-hover:text-blue-600 dark:group-hover:text-blue-400 transition-colors line-clamp-2 leading-snug">
                  {tc.title}
                </h3>

                {/* Description snippet */}
                {tc.description && (
                  <p className="text-xs text-slate-500 dark:text-slate-400 line-clamp-2 leading-normal">
                    {tc.description}
                  </p>
                )}
              </div>

              {/* Card Footer: Metadata & Actions */}
              <div className="pt-3 border-t border-slate-100 dark:border-slate-800/80 flex items-center justify-between text-xs">
                <div className="flex items-center space-x-2 text-slate-400 dark:text-slate-500 text-[11px]">
                  {/* Type Badge */}
                  <span
                    className={`text-[9px] px-1.5 py-0.5 rounded border font-mono font-semibold ${getTypeBadge(
                      tc.type
                    )}`}
                  >
                    {tc.type}
                  </span>

                  {/* Step Count */}
                  <span className="flex items-center space-x-0.5" title={`${tc.steps?.length || 0} Test Adımı`}>
                    <ListOrdered className="w-3 h-3" />
                    <span>{tc.steps?.length || 0}</span>
                  </span>

                  {/* Screenshot Indicator */}
                  {tc.screenshotUrl && (
                    <span className="flex items-center space-x-0.5 text-emerald-500" title="Görsel Ekli">
                      <ImageIcon className="w-3 h-3" />
                    </span>
                  )}

                  {/* Jira Story Indicator */}
                  {tc.jiraStoryKey && (
                    <span className="flex items-center space-x-0.5 text-blue-500 font-mono text-[9px]" title={`Jira: ${tc.jiraStoryKey}`}>
                      <Sparkles className="w-2.5 h-2.5" />
                      <span>{tc.jiraStoryKey}</span>
                    </span>
                  )}
                </div>

                <div className="flex items-center space-x-1">
                  {onRunCase && (
                    <button
                      type="button"
                      onClick={(e) => {
                        e.stopPropagation();
                        onRunCase(tc);
                      }}
                      className="px-2.5 py-1 rounded-lg bg-emerald-500/10 hover:bg-emerald-500/20 text-emerald-600 dark:text-emerald-400 border border-emerald-500/30 text-[11px] font-semibold flex items-center space-x-1 transition-all"
                      title="Senaryoyu Koştur"
                    >
                      <Play className="w-3 h-3 fill-current" />
                      <span>Run</span>
                    </button>
                  )}

                  <span className="p-1 text-slate-400 group-hover:text-blue-500 transition-colors">
                    <ChevronRight className="w-4 h-4" />
                  </span>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </main>
  );
};

export const ExplorerTree: React.FC<ExplorerTreeProps> = ({
  tree,
  selectedProject,
  selectedCaseId,
  selectedSuiteId,
  onSelectCase,
  onSelectSuite,
  onAddSubSuite,
  onEditSuite,
  onDeleteSuite,
  onAddCaseInSuite,
  onOpenNewSuite,
  onOpenNewCase,
  onRunCase,
  onRunSuite,
  onReorderSuite,
}) => {
  const [expandedMap, setExpandedMap] = useState<Record<string, boolean>>({});
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState<StatusFilter>('ALL');
  const [draggedSuiteId, setDraggedSuiteId] = useState<string | null>(null);
  const [dragOverSuiteId, setDragOverSuiteId] = useState<string | null>(null);

  const toggleExpand = (suiteId: string, e?: React.MouseEvent) => {
    if (e) e.stopPropagation();
    setExpandedMap((prev) => ({ ...prev, [suiteId]: !prev[suiteId] }));
  };

  const handleExpandAll = () => {
    const map: Record<string, boolean> = {};
    const traverse = (nodes: SuiteTreeNode[]) => {
      nodes.forEach((n) => {
        map[n.id] = true;
        if (n.children) traverse(n.children);
      });
    };
    traverse(tree);
    setExpandedMap(map);
  };

  const handleCollapseAll = () => {
    const map: Record<string, boolean> = {};
    const traverse = (nodes: SuiteTreeNode[]) => {
      nodes.forEach((n) => {
        map[n.id] = false;
        if (n.children) traverse(n.children);
      });
    };
    traverse(tree);
    setExpandedMap(map);
  };

  const getPriorityColor = (priority: string) => {
    switch (priority) {
      case 'BLOCKER':
        return 'bg-red-500/10 dark:bg-red-500/20 text-red-600 dark:text-red-400 border-red-500/30';
      case 'CRITICAL':
        return 'bg-amber-500/10 dark:bg-amber-500/20 text-amber-600 dark:text-amber-400 border-amber-500/30';
      case 'NORMAL':
        return 'bg-blue-500/10 dark:bg-blue-500/20 text-blue-600 dark:text-blue-400 border-blue-500/30';
      case 'LOW':
        return 'bg-slate-500/10 dark:bg-slate-500/20 text-slate-600 dark:text-slate-400 border-slate-500/30';
      default:
        return 'bg-slate-500/10 dark:bg-slate-500/20 text-slate-600 dark:text-slate-400 border-slate-500/30';
    }
  };

  const getTypeBadge = (type: string) => {
    switch (type) {
      case 'WEB':
        return 'text-emerald-500 dark:text-emerald-400';
      case 'MOBILE':
        return 'text-purple-500 dark:text-purple-400';
      case 'API':
        return 'text-cyan-500 dark:text-cyan-400';
      default:
        return 'text-slate-400';
    }
  };

  const getLatestStatusBadge = (testCase: TestCase) => {
    const latestResult = testCase.results && testCase.results.length > 0 ? testCase.results[0] : null;
    const status = latestResult?.status;

    switch (status) {
      case 'PASSED':
        return (
          <span
            className="flex items-center space-x-1 text-[9px] px-1.5 py-0.5 rounded bg-emerald-500/10 dark:bg-emerald-500/20 text-emerald-600 dark:text-emerald-400 border border-emerald-500/30 font-mono font-bold"
            title={`Sonuç: PASSED (${latestResult?.executedAt ? new Date(latestResult.executedAt).toLocaleTimeString() : ''})`}
          >
            <CheckCircle2 className="w-2.5 h-2.5" />
            <span>PASS</span>
          </span>
        );
      case 'FAILED':
        return (
          <span
            className="flex items-center space-x-1 text-[9px] px-1.5 py-0.5 rounded bg-red-500/10 dark:bg-red-500/20 text-red-600 dark:text-red-400 border border-red-500/30 font-mono font-bold"
            title={`Sonuç: FAILED ${latestResult?.errorMessage ? `- ${latestResult.errorMessage}` : ''}`}
          >
            <XCircle className="w-2.5 h-2.5" />
            <span>FAIL</span>
          </span>
        );
      case 'SKIPPED':
        return (
          <span
            className="flex items-center space-x-1 text-[9px] px-1.5 py-0.5 rounded bg-slate-500/10 dark:bg-slate-500/20 text-slate-600 dark:text-slate-400 border border-slate-500/30 font-mono font-bold"
            title="Sonuç: SKIPPED"
          >
            <SkipForward className="w-2.5 h-2.5" />
            <span>SKIP</span>
          </span>
        );
      case 'BLOCKED':
        return (
          <span
            className="flex items-center space-x-1 text-[9px] px-1.5 py-0.5 rounded bg-purple-500/10 dark:bg-purple-500/20 text-purple-600 dark:text-purple-400 border border-purple-500/30 font-mono font-bold"
            title="Sonuç: BLOCKED"
          >
            <Slash className="w-2.5 h-2.5" />
            <span>BLOCK</span>
          </span>
        );
      default:
        return (
          <span
            className="text-[9px] px-1.5 py-0.5 rounded bg-slate-200 dark:bg-slate-800 text-slate-500 dark:text-slate-400 border border-slate-300 dark:border-slate-700/50 font-mono"
            title="Henüz koşturulmadı"
          >
            -
          </span>
        );
    }
  };

  const handleDragStart = (e: React.DragEvent, suiteId: string) => {
    e.stopPropagation();
    setDraggedSuiteId(suiteId);
    e.dataTransfer.setData('text/plain', suiteId);
  };

  const handleDragOver = (e: React.DragEvent, suiteId: string) => {
    e.preventDefault();
    e.stopPropagation();
    if (draggedSuiteId !== suiteId) {
      setDragOverSuiteId(suiteId);
    }
  };

  const handleDrop = (e: React.DragEvent, targetSuiteId: string) => {
    e.preventDefault();
    e.stopPropagation();
    setDragOverSuiteId(null);
    if (draggedSuiteId && draggedSuiteId !== targetSuiteId && onReorderSuite) {
      onReorderSuite(draggedSuiteId, targetSuiteId, 0);
      setDraggedSuiteId(null);
    }
  };

  const matchCaseStatus = (tc: TestCase) => {
    if (statusFilter === 'ALL') return true;
    const status = tc.results && tc.results.length > 0 ? tc.results[0].status : 'UNTESTED';
    if (statusFilter === 'UNTESTED') return !tc.results || tc.results.length === 0;
    return status === statusFilter;
  };

  const renderSuiteNode = (node: SuiteTreeNode, depth: number = 0) => {
    const isExpanded = expandedMap[node.id] ?? true;
    const isDragOver = dragOverSuiteId === node.id;
    const isSuiteSelected = selectedSuiteId === node.id;

    // Filter testcases if search query or status filter exists
    const filteredCases = node.testCases.filter((c) => {
      const matchesSearch = searchQuery
        ? c.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
          c.code.toLowerCase().includes(searchQuery.toLowerCase())
        : true;
      const matchesStatus = matchCaseStatus(c);
      return matchesSearch && matchesStatus;
    });

    return (
      <div key={node.id} className="select-none">
        {/* Suite Header Item */}
        <div
          draggable
          onDragStart={(e) => handleDragStart(e, node.id)}
          onDragOver={(e) => handleDragOver(e, node.id)}
          onDrop={(e) => handleDrop(e, node.id)}
          onDragLeave={() => setDragOverSuiteId(null)}
          style={{ paddingLeft: `${depth * 14 + 12}px` }}
          className={`group flex items-center justify-between py-1.5 pr-2 rounded-lg transition-colors cursor-pointer text-xs font-medium ${
            isDragOver
              ? 'bg-blue-600/20 border border-blue-500'
              : isSuiteSelected
              ? 'bg-amber-500/15 dark:bg-amber-500/20 text-amber-900 dark:text-amber-200 font-bold border-l-2 border-amber-500 shadow-sm'
              : 'hover:bg-slate-200/60 dark:hover:bg-slate-800/70 text-slate-700 dark:text-slate-300 hover:text-slate-900 dark:hover:text-white'
          }`}
          onClick={(e) => {
            toggleExpand(node.id, e);
            if (onSelectSuite) onSelectSuite(node);
          }}
        >
          <div className="flex items-center space-x-1.5 min-w-0">
            <span className="opacity-0 group-hover:opacity-40 cursor-grab hover:opacity-100 transition-opacity">
              <GripVertical className="w-3 h-3" />
            </span>

            <button
              onClick={(e) => toggleExpand(node.id, e)}
              className="p-0.5 text-slate-400 hover:text-slate-700 dark:hover:text-white rounded"
            >
              {isExpanded ? (
                <ChevronDown className="w-3.5 h-3.5" />
              ) : (
                <ChevronRight className="w-3.5 h-3.5" />
              )}
            </button>

            {isExpanded ? (
              <FolderOpen className="w-4 h-4 text-amber-500 dark:text-amber-400 shrink-0" />
            ) : (
              <Folder className="w-4 h-4 text-amber-500/80 dark:text-amber-400/80 shrink-0" />
            )}

            <span className="truncate font-semibold text-slate-800 dark:text-slate-200">{node.name}</span>
            <span className="text-[10px] text-slate-400 dark:text-slate-500 font-mono ml-1">
              ({node.testCases.length})
            </span>
          </div>

          {/* Quick Actions for Suite */}
          <div className="opacity-0 group-hover:opacity-100 flex items-center space-x-1 transition-opacity">
            <button
              onClick={(e) => {
                e.stopPropagation();
                onAddCaseInSuite(node.id);
              }}
              title="Test Case Ekle"
              className="p-1 rounded hover:bg-slate-300 dark:hover:bg-slate-700 text-slate-500 dark:text-slate-400 hover:text-blue-600 dark:hover:text-blue-400"
            >
              <Plus className="w-3 h-3" />
            </button>

            {onRunSuite && node.testCases.length > 0 && (
              <button
                onClick={(e) => {
                  e.stopPropagation();
                  onRunSuite(node);
                }}
                title="Suite İçindeki Tüm Senaryoları Koştur (Run Suite)"
                className="p-1 rounded hover:bg-slate-300 dark:hover:bg-slate-700 text-emerald-600 dark:text-emerald-400 hover:text-emerald-500 font-bold"
              >
                <Play className="w-3 h-3 fill-current" />
              </button>
            )}

            {onEditSuite && (
              <button
                onClick={(e) => {
                  e.stopPropagation();
                  onEditSuite(node);
                }}
                title="Suite Düzenle"
                className="p-1 rounded hover:bg-slate-300 dark:hover:bg-slate-700 text-slate-500 dark:text-slate-400 hover:text-amber-500"
              >
                <Pencil className="w-3 h-3" />
              </button>
            )}

            {onDeleteSuite && (
              <button
                onClick={(e) => {
                  e.stopPropagation();
                  if (confirm(`"${node.name}" isimli suite klasörünü silmek istediğinize emin misiniz?`)) {
                    onDeleteSuite(node.id);
                  }
                }}
                title="Suite Sil"
                className="p-1 rounded hover:bg-slate-300 dark:hover:bg-slate-700 text-slate-500 dark:text-slate-400 hover:text-red-500"
              >
                <Trash2 className="w-3 h-3" />
              </button>
            )}
          </div>
        </div>

        {/* Children & Test Cases */}
        {isExpanded && (
          <div className="space-y-0.5">
            {/* Child Suites */}
            {node.children.map((childNode) => renderSuiteNode(childNode, depth + 1))}

            {/* Test Cases inside this suite */}
            {filteredCases.map((tc) => {
              const isSelected = selectedCaseId === tc.id;
              return (
                <div
                  key={tc.id}
                  style={{ paddingLeft: `${(depth + 1) * 14 + 18}px` }}
                  onClick={() => onSelectCase(tc)}
                  className={`group flex items-center justify-between py-1.5 pr-2 rounded-lg transition-all cursor-pointer text-xs ${
                    isSelected
                      ? 'bg-blue-500/10 dark:bg-blue-600/20 text-blue-700 dark:text-blue-300 font-semibold border-l-2 border-blue-500 shadow-sm'
                      : 'hover:bg-slate-200/50 dark:hover:bg-slate-800/50 text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-slate-200'
                  }`}
                >
                  <div className="flex items-center space-x-2 min-w-0 flex-1 mr-2">
                    <FileText className={`w-3.5 h-3.5 shrink-0 ${getTypeBadge(tc.type)}`} />
                    <span className="font-mono text-[10px] text-slate-400 dark:text-slate-500 shrink-0 font-bold">
                      {tc.code}
                    </span>
                    <span className="truncate">{tc.title}</span>
                  </div>

                  <div className="flex items-center space-x-1.5 shrink-0">
                    {/* Latest Status Badge */}
                    {getLatestStatusBadge(tc)}

                    {/* Run Command Button */}
                    {onRunCase && (
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          onRunCase(tc);
                        }}
                        title="Senaryoyu Koştur (Run)"
                        className="p-1 rounded bg-emerald-500/10 hover:bg-emerald-500/20 text-emerald-600 dark:text-emerald-400 border border-emerald-500/30 flex items-center space-x-1 transition-all opacity-0 group-hover:opacity-100 font-semibold text-[10px]"
                      >
                        <Play className="w-3 h-3 fill-current text-emerald-500" />
                        <span>Run</span>
                      </button>
                    )}

                    <span
                      className={`text-[9px] px-1.5 py-0.5 rounded border font-mono font-bold ${getPriorityColor(
                        tc.priority
                      )}`}
                    >
                      {tc.priority}
                    </span>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>
    );
  };

  return (
    <aside className="w-80 border-r border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900/50 flex flex-col h-[calc(100vh-4rem)] select-none transition-colors duration-200">
      {/* Active Test Plan Info & Actions */}
      {selectedProject && (
        <div className="p-3.5 bg-slate-50/80 dark:bg-slate-900/80 border-b border-slate-200 dark:border-slate-800 space-y-2.5">
          <div className="flex items-center justify-between">
            <div className="flex items-center space-x-2 min-w-0">
              <span className="font-mono text-[10px] font-bold px-2 py-0.5 rounded bg-rose-500/10 text-rose-600 dark:text-rose-400 border border-rose-500/20 shrink-0">
                [{selectedProject.key}]
              </span>
              <h2 className="text-xs font-bold text-slate-800 dark:text-slate-100 truncate" title={selectedProject.name}>
                {selectedProject.name}
              </h2>
            </div>
            <span className="text-[10px] text-slate-400 font-mono shrink-0">Test Planı</span>
          </div>

          {/* Plan-level Buttons: Yeni Suite & Yeni Case */}
          <div className="grid grid-cols-2 gap-2 pt-1">
            <button
              onClick={() => onOpenNewSuite ? onOpenNewSuite() : onAddSubSuite('')}
              className="flex items-center justify-center space-x-1.5 px-2.5 py-1.5 text-xs font-semibold bg-amber-500/10 hover:bg-amber-500/20 text-amber-700 dark:text-amber-300 border border-amber-500/30 rounded-lg transition-all shadow-sm active:scale-95 cursor-pointer"
              title="Plan Altında Yeni Suite Oluştur"
            >
              <FolderPlus className="w-3.5 h-3.5 text-amber-500 shrink-0" />
              <span>+ Yeni Suite</span>
            </button>

            <button
              onClick={() => onOpenNewCase ? onOpenNewCase() : onAddCaseInSuite('')}
              className="flex items-center justify-center space-x-1.5 px-2.5 py-1.5 text-xs font-semibold bg-blue-500/10 hover:bg-blue-500/20 text-blue-700 dark:text-blue-300 border border-blue-500/30 rounded-lg transition-all shadow-sm active:scale-95 cursor-pointer"
              title="Plan Altında Yeni Case Oluştur"
            >
              <FilePlus className="w-3.5 h-3.5 text-blue-500 shrink-0" />
              <span>+ Yeni Case</span>
            </button>
          </div>
        </div>
      )}

      {/* Explorer Tree Toolbar & Search */}
      <div className="p-3.5 border-b border-slate-200 dark:border-slate-800 space-y-2.5">
        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-2">
            <Layers className="w-4 h-4 text-blue-500" />
            <h2 className="text-xs font-bold uppercase tracking-wider text-slate-700 dark:text-slate-300">Explorer</h2>
          </div>
          <div className="flex items-center space-x-1">
            <button
              onClick={handleExpandAll}
              className="p-1 rounded hover:bg-slate-100 dark:hover:bg-slate-800 text-slate-400 hover:text-slate-700 dark:hover:text-slate-200 transition-colors"
              title="Tümünü Genişlet (Expand All)"
            >
              <Maximize2 className="w-3 h-3" />
            </button>
            <button
              onClick={handleCollapseAll}
              className="p-1 rounded hover:bg-slate-100 dark:hover:bg-slate-800 text-slate-400 hover:text-slate-700 dark:hover:text-slate-200 transition-colors"
              title="Tümünü Daralt (Collapse All)"
            >
              <Minimize2 className="w-3 h-3" />
            </button>
          </div>
        </div>

        {/* Search Input */}
        <div className="relative">
          <Search className="w-3.5 h-3.5 text-slate-400 absolute left-2.5 top-1/2 -translate-y-1/2" />
          <input
            type="text"
            placeholder="Case ya da Kod ara..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full bg-slate-100 dark:bg-slate-900/80 border border-slate-200 dark:border-slate-800 rounded-lg text-xs text-slate-800 dark:text-slate-200 placeholder-slate-400 dark:placeholder-slate-500 pl-8 pr-3 py-1.5 focus:outline-none focus:ring-1 focus:ring-blue-500 transition-colors"
          />
        </div>

        {/* Status Filter Chips */}
        <div className="flex items-center space-x-1 overflow-x-auto pb-0.5 text-[10px] font-medium">
          <button
            onClick={() => setStatusFilter('ALL')}
            className={`px-2 py-0.5 rounded-full border transition-colors ${
              statusFilter === 'ALL'
                ? 'bg-blue-600 text-white border-blue-600'
                : 'bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400 border-slate-200 dark:border-slate-700'
            }`}
          >
            Tümü
          </button>
          <button
            onClick={() => setStatusFilter('PASSED')}
            className={`px-2 py-0.5 rounded-full border transition-colors ${
              statusFilter === 'PASSED'
                ? 'bg-emerald-600 text-white border-emerald-600'
                : 'bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border-emerald-500/30'
            }`}
          >
            Pass
          </button>
          <button
            onClick={() => setStatusFilter('FAILED')}
            className={`px-2 py-0.5 rounded-full border transition-colors ${
              statusFilter === 'FAILED'
                ? 'bg-red-600 text-white border-red-600'
                : 'bg-red-500/10 text-red-600 dark:text-red-400 border-red-500/30'
            }`}
          >
            Fail
          </button>
          <button
            onClick={() => setStatusFilter('BLOCKED')}
            className={`px-2 py-0.5 rounded-full border transition-colors ${
              statusFilter === 'BLOCKED'
                ? 'bg-purple-600 text-white border-purple-600'
                : 'bg-purple-500/10 text-purple-600 dark:text-purple-400 border-purple-500/30'
            }`}
          >
            Block
          </button>
          <button
            onClick={() => setStatusFilter('UNTESTED')}
            className={`px-2 py-0.5 rounded-full border transition-colors ${
              statusFilter === 'UNTESTED'
                ? 'bg-slate-600 text-white border-slate-600'
                : 'bg-slate-200 dark:bg-slate-800 text-slate-500 border-slate-300 dark:border-slate-700'
            }`}
          >
            Koşulmadı
          </button>
        </div>
      </div>

      {/* Tree View Scrollable Content */}
      <div className="flex-1 overflow-y-auto p-2 space-y-1">
        {tree.length === 0 ? (
          <div className="text-center py-10 px-4 text-slate-400 dark:text-slate-500 text-xs">
            <Folder className="w-8 h-8 mx-auto mb-2 opacity-30 text-slate-400" />
            <p>Henüz klasör (Suite) bulunmuyor.</p>
            <p className="text-[10px] mt-1 text-slate-500">Yukarıdaki "+ Yeni Suite" butonundan klasör ekleyebilirsiniz.</p>
          </div>
        ) : (
          tree.map((node) => renderSuiteNode(node, 0))
        )}
      </div>
    </aside>
  );
};

export const NewCaseModal: React.FC<NewCaseModalProps> = ({
